import { Transform } from 'node:stream';
import commitFileAsync from './actions/commit-file-async.js';
export const createCommitTransform = () => new Transform({
    objectMode: true,
    transform(file, _encoding, callback) {
        commitFileAsync(file)
            .then(() => {
            callback(null, file);
        })
            .catch(callback);
    },
});
